refentry.refsect1:
  &reftitle.description;

   truenatsort
   arrayarray


यो function ले एउटा यस्तो sort algorithm implement गर्छ, जसले key/value बीचको सम्बन्ध कायम राख्दै alphanumeric strings लाई मानिसले गर्ने तरिकाले क्रमबद्ध गर्छ। यसलाई "natural ordering" भनिन्छ। यो algorithm र (sort मा प्रयोग हुने) नियमित computer string sorting algorithm बीचको भिन्नताको एउटा उदाहरण तल देख्न सकिन्छ।
  &note.sort-unstable;
  &note.reset-index;

  &reftitle.examples;



    natsort को आधारभूत प्रयोग देखाउने उदाहरणहरू


<?php
$array1 = $array2 = array("img12.png", "img10.png", "img2.png", "img1.png");

asort($array1);
echo "Standard sorting\n";
print_r($array1);

natsort($array2);
echo "\nNatural order sorting\n";
print_r($array2);
?>


    &example.outputs;


Standard sorting
Array
(
    [3] => img1.png
    [1] => img10.png
    [0] => img12.png
    [2] => img2.png
)

Natural order sorting
Array
(
    [3] => img1.png
    [2] => img2.png
    [1] => img10.png
    [0] => img12.png
)



थप जानकारीका लागि हेर्नुहोस्: Martin Pool को Natural Order String Comparison page।


    natsort का सम्भावित समस्याहरू (gotchas) देखाउने उदाहरणहरू


<?php
echo "Negative numbers\n";
$negative = array('-5','3','-2','0','-1000','9','1');
print_r($negative);
natsort($negative);
print_r($negative);

echo "Zero padding\n";
$zeros = array('09', '8', '10', '009', '011', '0'); 
print_r($zeros);
natsort($zeros);
print_r($zeros);
?>


    &example.outputs;


Negative numbers
Array
(
    [0] => -5
    [1] => 3
    [2] => -2
    [3] => 0
    [4] => -1000
    [5] => 9
    [6] => 1
)
Array
(
    [2] => -2
    [0] => -5
    [4] => -1000
    [3] => 0
    [6] => 1
    [1] => 3
    [5] => 9
)
Zero padding
Array
(
    [0] => 09
    [1] => 8
    [2] => 10
    [3] => 009
    [4] => 011
    [5] => 0
)
Array
(
    [5] => 0
    [1] => 8
    [0] => 09
    [3] => 009
    [2] => 10
    [4] => 011
)
